"""Evidence register with conditional numerical gates and explicit unsolved product tests."""
import os,sys,json,hashlib,csv
from pathlib import Path
P=Path(__file__).parent;O=P/'engineering-v18-results';sys.path.insert(0,str(P/'solver-libraries'));import numpy as np
def audit(f):
 r=json.loads(f.read_text());assert hashlib.sha256(Path(r['source']).read_bytes()).hexdigest()==r['source_sha256']
 with np.load(f.with_suffix('.npz')) as a:
  work=float(a['force']@a['u'].ravel());energy=abs(2*r['strain_energy_Nmm']-work)/max(abs(work),1e-20);balance=float(np.linalg.norm(np.array(r['reaction_sum_N'])+a['force'].reshape(-1,3).sum(axis=0)));fixed=float(np.max(np.abs(a['u'].ravel()[a['fixed']])));finite=all(np.isfinite(a[k]).all() for k in a.files)
  r['array_audit']=dict(file=str(f.with_suffix('.npz')),sha256=hashlib.sha256(f.with_suffix('.npz').read_bytes()).hexdigest(),work_energy_relative_error=energy,force_balance_error_N=balance,fixed_displacement_mm=fixed,finite=bool(finite),pass_result=bool(finite and energy<1e-6 and balance<1e-6 and fixed<1e-12 and r['relative_free_residual']<1e-6 and r['minimum_adaptive_Jacobian_mm3']>0))
 return r
stops=[]
for size in ['child_large','adult_small']:
 m=[audit(O/(size+'_stop_h'+str(h)+'.json')) for h in [2.0,1.5]];dc=abs(m[0]['weighted_load_direction_displacement_mm']/m[1]['weighted_load_direction_displacement_mm']-1);sc=abs(m[0]['max_von_mises_centroid_MPa']/m[1]['max_von_mises_centroid_MPa']-1);stops.append(dict(size=size,meshes=m,displacement_change_fraction=dc,stress_change_fraction=sc,chosen_mesh_gate_pass=max(dc,sc)<.05))
bands=json.loads((O/'band_refinement.json').read_text());assert bands['complete']
for r in bands['cases']:r['meshes']=[audit(O/(r['size']+'_full_width_h'+str(m['mesh_max_mm'])+'.json')) for m in r['meshes']]
arrays=[m['array_audit'] for r in stops+bands['cases'] for m in r['meshes']];assert all(a['pass_result'] for a in arrays)
equiv=json.loads((O/'component_equivalence.json').read_text());component=[r for r in equiv['records'] if r['part']!='Band'];assert len(component)==12 and all(r['pass_result'] for r in component)
torque=json.loads((O/'torque_and_mass.json').read_text());exports=json.loads((O/'STEP_verification.json').read_text());assert exports['all_pass']
sizes=[]
for f in sorted(O.glob('*_cad_report.json')):
 c=json.loads(f.read_text());a=json.loads((O/(c['size']+'_motion_audit.json')).read_text());assert a['source_sha256']==c['sha256'] and a['sampled_motion_pass'] and a['wearing_stop_blocking_pass'];rv=np.prod(a['retracted_box_mm']);fv=np.prod(a['folded_box_mm']);sizes.append(dict(size=c['size'],source=c['file'],source_sha256=c['sha256'],motion_samples=a['case_count'],valid_solids=len(a['validity']),stop_queries=len(a['wearing_stop_queries']),retracted_box_mm=a['retracted_box_mm'],folded_box_mm=a['folded_box_mm'],folded_to_retracted_box_volume_ratio=float(fv/rv),fold_extension_mm=c['fold_extension_mm'],fold_angles_deg=c['fold_angles_deg'],guide_bottom_mm=c['guide_bottom_mm']))
loads=[]
for sideforce in [.5,2,5,10,20]:
 sf=sideforce*65/10;loads.append(dict(illustrative_side_force_N=sideforce,assumed_lever_mm=65,stop_reaction_at10mm_N=sf,nominal_two_patch_pressure_MPa=sf/32,scope='Statics and nominal area only. Not local peak pressure, impact, fatigue or a strength pass.'))
tests=[('Six size local CAD','Recorded pass','38 valid solids per size; native Fusion archives remain V10'),('Rigid motion','Recorded sampled pass',str(sum(r['motion_samples'] for r in sizes))+' finite poses; not continuous contact or handling qualification'),('Independent saved poses','Recorded pass','18 STEP files reimported for count validity volume and bounds'),('Stop fixtures','Conditional mesh comparisons','Two geometry families, ideal stem clamp and assumed homogeneous material'),('Band fixtures','Conditional mesh comparisons','All six sizes independently rerun with ideal supports and assumed E2000 MPa'),('Static gravity holding','Conditional comparison pass','18 assumed density cases below proposed64Nmm minimum; actual torque unmeasured'),('Torque calibration and retention','Not performed','Measure real breakaway and running torque, locking, drift and wear'),('Complete joint strength','Not established','Actual fork stop bearing guide bolt preload and contact load sharing remain unsolved'),('Folded portability','Geometry recorded','Bounding boxes are compared; no carrying usability or optimized packing claim'),('Materials','Not selected or validated','Earlier finite reference screens are not exhaustive and require samples'),('Acoustics and outgoing leakage','No physical pass','Actual repeated-seating attenuation leakage response and ANC tests needed'),('Comfort heat and sensory acceptance','No physical pass','Voluntary user feedback and measured pressure temperature humidity needed'),('Durability and child handling','Not performed','Drop cycles cleaning ageing pinch and small-part retention require assembled samples'),('Sony WH CH720N pad','Measurements deferred','No model-specific mounting fit seal sound or comfort pass'),('Cost and production','Not released','Supplier quotes process capability tooling and actual assembly required')]
out=dict(revision='V18 passive friction hinge and wearing stop',updated='2026-10-16',sizes=sizes,stop_mechanics=stops,band_mechanics=bands,arrays=arrays,component_family_equivalence=component,nontransferable_band_boolean_checks=[r for r in equiv['records'] if r['part']=='Band'],nominal_stop_loads=loads,tests=[dict(zip(['test','status','scope'],r)) for r in tests],digital_prototype_candidate=True,product_complete=False,manufacturing_release=False,physical_tests_performed=0,native_Fusion_revision='V10',limits=['Mesh and geometry passes are conditional numerical evidence, not a validated product','The volume-common kernel did not establish child Band identity; all six bands were therefore solved again','Friction hinge deliberately permits inward folding and does not lock every load direction','Threaded fasteners are envelopes; spring shown at a catalogue reference height; actual assembly requires calibration'])
(O/'test_register.json').write_text(json.dumps(out,indent=2));folder=O/'physical-test-records';folder.mkdir(exist_ok=True)
for name,cols in [('hinge_torque.csv',['sample','size','material_lots','spring_part_lot','washer_pair','temperature_C','humidity_percent','cycles','direction','angle_deg','breakaway_Nmm','running_Nmm','nut_retention','stop_damage','notes']),('Sony_mount_measurements.csv',['headphone_model','pad_outer_height_mm','pad_outer_width_mm','pad_depth_mm','ear_opening_height_mm','ear_opening_width_mm','mount_type','lip_or_clip_dimensions','instrument_uncertainty','notes'])]:
 f=folder/name
 if not f.exists():
  with f.open('w',newline='') as file:csv.writer(file).writerow(cols)
lines=['# V18 digital prototype review','','The six-size local STEP candidate replaces the loaded sliding pin with a passive friction hinge and a separate wearing stop. This avoids that pin-return mechanism; it does not prove a complete reliable product.','',f"Recorded: {sum(r['motion_samples'] for r in sizes)} rigid pose samples,24 outward stop queries,18 independently reimported pose files,12 family component equality comparisons and {len(arrays)} saved finite-element array audits.",'','## Test status','']
lines += ['- '+a+': '+b+'. '+c+'.' for a,b,c in tests]
lines += ['','## Important limits','','The proposed hinge torque is80Nmm with a chosen20percent window. This is unmeasured and not a comfort threshold. Do not infer nut position or spring height from a single catalogue force point. The CAD spring is a reference envelope.','', 'The largest assumed gravity moment is '+str(round(max(r['maximum_gravity_moment_over_orientation_Nmm'] for r in torque['mass_cases']),2))+'Nmm. Static gravity comparison is not resistance to shocks or inadvertent folding.','', 'All real material properties, acoustic benefits, pressure comfort, sensory acceptance, climate behaviour and durability need calibration and physical samples. Sony mounting measurements are deferred. No universal market superiority, zero leakage, lowest price or manufacturing release is claimed.','', 'Native Fusion archives remain V10. Current V18 files are independently checked local STEP geometry. Both Word reports contain revision-specific history and shared limitations.']
(O/'REVIEW.md').write_text('\n'.join(lines));print(json.dumps(dict(sizes=len(sizes),pose_samples=sum(r['motion_samples'] for r in sizes),arrays=len(arrays),all_arrays_pass=True,band_mesh_comparisons=bands['all_chosen_comparisons_pass'],stop_mesh_comparisons=all(r['chosen_mesh_gate_pass'] for r in stops))))
